/* Fixed software authorship, separate from editable astrologer contact details. */
(()=>{'use strict';const NAME='Nitin Rajendra Talegaonkar',MOBILE='+918412098690',CREDIT='Software Developer Name: '+NAME+' · Mob: '+MOBILE;
function apply(root=document){const value=id=>document.getElementById(id)?.value.trim()||'',astro=[value('astroName')?'Astrologer: '+value('astroName'):'',value('astroAddress')?'Address: '+value('astroAddress'):'',value('astroMobile')?'Contact: '+value('astroMobile'):''].filter(Boolean).join(' · ');for(const footer of root.querySelectorAll('.report-developer-footer')){footer.dataset.fixedDeveloper='true';footer.replaceChildren();if(astro){const line=root.ownerDocument?.createElement('div')||root.createElement('div');line.className='report-astrologer-credit';line.textContent=astro;footer.append(line);}const line=root.ownerDocument?.createElement('div')||root.createElement('div');line.className='report-fixed-developer-credit';line.dataset.noLocalize='true';line.textContent=CREDIT;footer.append(line);}const footer=root.querySelector('#softwareDeveloperFooter');if(footer){footer.textContent=CREDIT;footer.dataset.noLocalize='true';}}
const oldRender=window.renderReport;if(oldRender)window.renderReport=function(...args){const result=oldRender.apply(this,args);apply();return result;};const oldApply=window.applyAstrologerSettings;if(oldApply)window.applyAstrologerSettings=function(...args){const result=oldApply.apply(this,args);apply();return result;};
function init(){apply();document.addEventListener('click',e=>{if(e.target.closest('#settings-save,[onclick="saveAstrologerSettings()"],[onclick="resetAstrologerSettings()"]'))setTimeout(()=>apply(),0);});window.addEventListener('kp-preferences-changed',()=>apply());}
window.KPDeveloperCredit=Object.freeze({name:NAME,mobile:MOBILE,text:CREDIT,apply});if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',()=>setTimeout(init,100));else init();})();
